(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n===null?'Preço sob consulta':(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const id=location.pathname.split('/')[2];
 fetch('/api/catalog').then(r=>r.json()).then(d=>{let mode='default';try{mode=localStorage.getItem('up-visitor-theme')||mode;}catch{}applyTheme({...d.settings,theme:mode==='default'?d.settings.theme:mode});}).catch(()=>{});
 async function load(){try{const r=await fetch('/api/products/'+encodeURIComponent(id)),data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível carregar este produto.');const p=data.product,d=p.details;document.title=p.name+' | Up Smart Varginha';const photos=[...new Set([p.image,...d.gallery].filter(Boolean))];const v=d.variants;const content=$('#product-content');content.innerHTML=`<div class="product-detail-grid"><div class="product-gallery"><div class="product-main-photo">${photos.length?`<img id="main-photo" src="${esc(photos[0])}" alt="${esc(p.name)} — foto 1" referrerpolicy="no-referrer">`:'<p>Foto em breve</p>'}</div>${photos.length>1?`<div class="product-thumbs" aria-label="Galeria de fotos">${photos.map((src,i)=>`<button type="button" data-photo="${i}" aria-label="Ver foto ${i+1}" aria-pressed="${i===0}"><img src="${esc(src)}" alt="" referrerpolicy="no-referrer"></button>`).join('')}</div>`:''}</div><div class="product-information"><p class="eyebrow dark">${esc(p.category)} · ${esc(p.condition)}</p><h1>${esc(p.name)}</h1><p class="product-description">${esc(p.description)}</p>${v.length?`<label class="option-label" for="product-option">Escolha sua opção</label><select id="product-option">${v.map((x,i)=>`<option value="${i}">${esc([x.color,x.capacity].filter(Boolean).join(' · '))}${x.stock===0?' — sem estoque':''}</option>`).join('')}</select>`:`<div class="product-spec-chips">${[d.color,d.capacity].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}<p class="detail-price" id="detail-price"></p><p id="detail-stock" class="detail-stock" aria-live="polite"></p><div class="product-actions"><a id="product-interest" class="button orange" target="_blank" rel="noopener noreferrer">Tenho interesse ↗</a><button type="button" class="favorite-button" data-favorite="${esc(p.id)}" aria-pressed="false">♡ Salvar favorito</button></div><p class="purchase-note">Converse com a equipe para confirmar a disponibilidade e as condições de compra.</p><div class="product-facts">${p.condition==='Seminovo'&&d.battery!==null?`<div><h2>Saúde da bateria</h2><p>${d.battery}% · informação fornecida pela loja</p></div>`:''}${d.warranty?`<div><h2>Garantia</h2><p>${esc(d.warranty)}</p></div>`:''}${d.specs?`<div><h2>Ficha técnica e itens inclusos</h2><p>${esc(d.specs)}</p></div>`:''}</div></div></div>`;
 const change=()=>{const selected=v.length?v[Number($('#product-option').value)]:{...p,color:d.color,capacity:d.capacity};$('#detail-price').textContent=money(selected.price);$('#detail-stock').textContent=selected.stock>0?'Disponível em estoque':'Sem estoque no momento';$('#detail-stock').classList.toggle('out',selected.stock===0);const option=[selected.color,selected.capacity].filter(Boolean).join(' · ');$('#product-interest').textContent=selected.stock>0?'Tenho interesse ↗':'Consultar reposição ↗';$('#product-interest').href='https://wa.me/553591558356?text='+encodeURIComponent(`Olá! ${selected.stock>0?'Tenho interesse em':'Gostaria de consultar a reposição de'} ${p.name}${option?' ('+option+')':''}.\nCondição: ${p.condition}.\n${selected.price===null?'Preço sob consulta.':'Preço anunciado: '+money(selected.price)+'.'}\n${location.origin+location.pathname}`);};
 if(v.length){const first=v.findIndex(x=>x.stock>0);$('#product-option').value=String(Math.max(0,first));$('#product-option').onchange=change;}change();
 content.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.photo),img=$('#main-photo');img.src=photos[i];img.alt=p.name+' — foto '+(i+1);content.querySelectorAll('[data-photo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
 const main=$('#main-photo');if(main)main.onerror=()=>{main.alt='Foto indisponível. Escolha outra imagem na galeria.';};
 $('#product-status').hidden=true;content.hidden=false;document.dispatchEvent(new Event('up:products-rendered'));
 }catch(e){$('#product-status').textContent=e.message;const a=document.createElement('a');a.href='/#produtos';a.className='text-link';a.textContent='Voltar à vitrine ↗';$('#product-status').after(a);}}
 load();
})();
